import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  // One journey across member and reviewer: the re-uploaded W9 is the one the reviewer sees.
  test(
    "a re-uploaded document is the one that gets reviewed",
    { tag: "@LIF-01" },
    async ({ apiAs, factory }) => {
      // Arrange: a draft vendor with the two non-W9 documents, then two W9s with different legal names.
      const member = await apiAs("member");
      const vendor = await factory.vendor({ as: "member" });
      await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate.txt", "member");
      await factory.upload(vendor.id, "contract", "contract.txt", "member");
      const w9Upload = (legalName: string) =>
        member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "w9",
            file: {
              name: "w9.txt",
              mimeType: "text/plain",
              buffer: Buffer.from(`Legal Name: ${legalName}\nTax ID: 84-2219067\nBusiness Type: LLC\n`),
            },
          },
        });
      const first = await expectStatus<{ id: string }>(await w9Upload("First Name LLC"), 201);
      const second = await expectStatus<{ id: string }>(await w9Upload("Second Name LLC"), 201);

      // Wait for every document to finish extraction before submitting.
      await expect
        .poll(
          async () => {
            const documents = await expectStatus<{ status: string }[]>(
              await member.get(`/api/vendors/${vendor.id}/documents`),
              200,
            );
            return documents.map((d) => d.status);
          },
          { message: "extraction finishes for all four documents", timeout: 30_000 },
        )
        .toEqual(["extracted", "extracted", "extracted", "extracted"]);

      // Act: the member submits, and a reviewer opens the review queue.
      await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
      const reviewer = await apiAs("reviewer");
      const queue = await expectStatus<
        { vendor_id: string; extractions: { kind: string; id: string; fields: Record<string, { value: string | null }> }[] }[]
      >(await reviewer.get("/api/review-queue"), 200);

      // Assert: the queue's W9 extraction carries the second upload's legal name.
      const item = queue.find((i) => i.vendor_id === vendor.id);
      expect(item, "submitted vendor appears in the review queue").toBeDefined();
      const w9Extraction = item!.extractions.find((e) => e.kind === "w9");
      expect(w9Extraction?.fields.legal_name.value).toBe("Second Name LLC");

      // Assert: the vendor's documents list both W9 uploads, oldest first.
      const documents = await expectStatus<{ id: string; kind: string; created_at: string }[]>(
        await member.get(`/api/vendors/${vendor.id}/documents`),
        200,
      );
      const w9Ids = documents.filter((d) => d.kind === "w9").map((d) => d.id);
      expect(w9Ids).toEqual([first.id, second.id]);
    },
  );
});
